<script setup>
import {computed,onUnmounted,ref,watch} from 'vue';import{collection,onSnapshot,query,where}from'firebase/firestore';import{db}from'../firebase/firebase'
const props=defineProps({identifier:{type:String,required:true},date:{type:String,required:true}}),rows=ref([]),loading=ref(false),error=ref('');let stop=null
watch(()=>[props.identifier,props.date],([identifier,date])=>{stop?.();rows.value=[];error.value='';if(!identifier||!date)return;loading.value=true;stop=onSnapshot(query(collection(db,'entries'),where('parcIdentifier','==',identifier)),snap=>{rows.value=snap.docs.map(d=>({id:d.id,...d.data()})).filter(r=>r.date===date);loading.value=false},()=>{error.value='Impossible de charger les informations de ce Lawson.';loading.value=false})},{immediate:true});onUnmounted(()=>stop?.())
const details=computed(()=>rows.value.flatMap(row=>(row.serviceIds||[]).map(id=>({id,name:id,normal:row.hours?.[id]||0,sup25:row.hours25?.[id]||0,sup50:row.hours50?.[id]||0,prorata:row.prorata?.[id]?(row.hours?.[id]||7):null}))))
</script>
<template><section class="lawson-history"><div class="panel-heading"><div><h2>Informations déjà saisies · {{identifier}}</h2><p>{{date}} · lecture seule</p></div><span class="badge">{{rows.length}} saisie(s)</span></div><p v-if="loading" class="muted">Chargement…</p><p v-else-if="error" class="error">{{error}}</p><p v-else-if="!details.length" class="muted">Aucune information enregistrée pour ce Lawson à cette date.</p><div v-else class="lawson-history-list"><div v-for="item in details" :key="`${item.id}-${item.normal}-${item.sup25}-${item.sup50}`"><strong>{{item.name}}</strong><span>Normal : {{item.normal}}</span><span>Sup 25 % : {{item.sup25}}</span><span>Sup 50 % : {{item.sup50}}</span><span v-if="item.prorata!==null">Prorata : {{item.prorata}} h / 7</span></div></div></section></template>
